insert into chart_templates
  (country, code, name, name_i18n, is_default, audience, statements,
   certification_status, legal_reference, source_key)
values
  ('CV', 'default', 'Código de Contas do SNCRF (Portaria n.º 49/2008) — selecção para sociedades comerciais', '{}'::jsonb, true, 'companies', array['CV-BS', 'CV-IS']::text[], null, 'Decreto-Lei n.º 5/2008 approves the Sistema de Normalização Contabilística e de Relato Financeiro and Portaria n.º 49/2008 publishes its Código de Contas, classes 1 to 7 (class 5 holds equity and the result, classes 6 and 7 the expenses and the income; there is no class 8). The chart carries the official codes and names, with the levels of detail a trading company posts to; it is a selection, not the whole code, and the official code leaves free levels where it prints «…». Where this pack adds a level the code leaves free, it says so: 68881 Arredondamentos (rounding) under 6888. The codes 24421 to 24423 (deductible VAT), 24431 to 24433 (VAT charged) and 24461 (VAT payable, amounts assessed) are the code''s own sub-accounts of 244.', 'portaria-49-2008')
