insert into tax_templates
  (country, code, name, name_i18n, description, amount_type, amount, applies_to, treatment,
   valid_from, valid_to, legal_reference, vat_category, exemption_code, sequence,
   tax_kind, recoverable, conditions, jurisdiction, price_include, cash_basis,
   cash_basis_transition_account_code, source_key,
   applies_seller_territory, applies_buyer_territory, applies_supply_territory,
   applies_supply_vs_seller)
values
  ('CV', 'CV-P-15-CAPEX', 'IVA 15 % dedutível — investimentos (compra)', '{}'::jsonb, null, 'percent', 15, 'purchase', 'domestic', date '2014-01-01', null, 'Código do IVA (Lei n.º 51/VIII/2013, republicação em anexo), articles 18 to 21: the tax borne on purchases for the business is deducted from the tax due in the period in which the invoice is received (article 21(3)); the Modelo 106 splits the deductible tax by kind of purchase. Field 17 and 18 (investments); account 24422. The pack does not model the exclusions of article 20 (for example passenger cars, representation) nor the partial deduction of article 22: a purchase that falls there is for the user''s accountant.', null, null, 90, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'civa-lei-51-2013', null, null, null, null),
  ('CV', 'CV-P-15-GOODS', 'IVA 15 % dedutível — outros bens de consumo (compra)', '{}'::jsonb, null, 'percent', 15, 'purchase', 'domestic', date '2014-01-01', null, 'Código do IVA (Lei n.º 51/VIII/2013, republicação em anexo), articles 18 to 21: the tax borne on purchases for the business is deducted from the tax due in the period in which the invoice is received (article 21(3)); the Modelo 106 splits the deductible tax by kind of purchase. Field 21 and 22 (other consumer goods); account 24423.', null, null, 100, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'civa-lei-51-2013', null, null, null, null),
  ('CV', 'CV-P-15-INV', 'IVA 15 % dedutível — inventários (compra)', '{}'::jsonb, null, 'percent', 15, 'purchase', 'domestic', date '2014-01-01', null, 'Código do IVA (Lei n.º 51/VIII/2013, republicação em anexo), articles 18 to 21: the tax borne on purchases for the business is deducted from the tax due in the period in which the invoice is received (article 21(3)); the Modelo 106 splits the deductible tax by kind of purchase. Field 19 and 20 of the Modelo 106 (inventories); account 24421 of the Código de Contas.', null, null, 80, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'civa-lei-51-2013', null, null, null, null),
  ('CV', 'CV-P-15-NR', 'IVA 15 % — serviços de prestador sem sede em Cabo Verde, liquidado pelo adquirente (compra)', '{}'::jsonb, 'VAT on a service bought from abroad is assessed by the buyer and deducted in the same return', 'percent', 15, 'purchase', 'foreign_services_received', date '2014-01-01', null, 'Código do IVA (Lei n.º 51/VIII/2013, republicação em anexo), article 6(6): licences, copyright and similar rights and the other services it lists, supplied by a provider with no seat, establishment or domicile in Cabo Verde to a taxable person established there, are taxable in Cabo Verde; article 23(2): the acquirer pays the tax with the periodic return. The Modelo 106 reports the base in field 11, the tax in favour of the taxpayer in field 12 and the tax in favour of the State in field 13. The pack posts the tax charged to 24433 (operações especiais) and the tax deductible to 24423, and reports both in the same period. Which services article 6(6) lists was read only to its first item (rights); check the others before using this code.', null, null, 120, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'civa-lei-51-2013', null, null, null, null),
  ('CV', 'CV-P-15-SERV', 'IVA 15 % dedutível — serviços (compra)', '{}'::jsonb, null, 'percent', 15, 'purchase', 'domestic', date '2014-01-01', null, 'Código do IVA (Lei n.º 51/VIII/2013, republicação em anexo), articles 18 to 21: the tax borne on purchases for the business is deducted from the tax due in the period in which the invoice is received (article 21(3)); the Modelo 106 splits the deductible tax by kind of purchase. Field 23 and 24 (services); account 24423.', null, null, 110, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'civa-lei-51-2013', null, null, null, null),
  ('CV', 'CV-S-15', 'IVA 15 % — taxa normal (venda)', '{}'::jsonb, null, 'percent', 15, 'sale', 'domestic', date '2014-01-01', null, 'Código do IVA (Lei n.º 51/VIII/2013, republicação em anexo), article 17(1): the rate of the tax is 15 %, the rate in force when the tax becomes chargeable (article 17(2)). One rate only: the Code has no reduced rate; goods and services that the legislator spares are exempt, not taxed at a lower rate. The 2015 amendment (Lei n.º 81/VIII/2014) leaves article 17 as republished in 2013. Later budget laws were not searched.', null, null, 10, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'civa-lei-51-2013', null, null, null, null),
  ('CV', 'CV-S-EXEMPT-AGRI', 'IVA isento — produção agrícola, silvícola, pecuária e de pesca (venda)', '{}'::jsonb, null, 'percent', 0, 'sale', 'exempt', date '2014-01-01', null, 'Código do IVA (Lei n.º 51/VIII/2013, republicação em anexo), article 9(30): supplies made within an agricultural, forestry, livestock or fishing activity, including the processing a producer does with the means normally used on a farm, are exempt without the right to deduct (field 09). The list of essential goods (article 9(28)) and of equipment and inputs (article 9(33)) is the Code''s annexed list, which was not read; add the item a case needs with its number on the list.', null, null, 70, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'civa-lei-51-2013', null, null, null, null),
  ('CV', 'CV-S-EXEMPT-EDU', 'IVA isento — ensino e formação profissional (venda)', '{}'::jsonb, null, 'percent', 0, 'sale', 'exempt', date '2014-01-01', null, 'Código do IVA (Lei n.º 51/VIII/2013, republicação em anexo), article 9(8) to (10): teaching services and related supplies by establishments of the national education system or recognised as equivalent, vocational training by recognised bodies, and lessons given personally from pre-school to higher education are exempt without the right to deduct (Modelo 106 field 09). The limits of «recognised» bodies are the Ministry''s, not read.', null, null, 30, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'civa-lei-51-2013', null, null, null, null),
  ('CV', 'CV-S-EXEMPT-FIN', 'IVA isento — operações bancárias e financeiras, seguros (venda)', '{}'::jsonb, null, 'percent', 0, 'sale', 'exempt', date '2014-01-01', null, 'Código do IVA (Lei n.º 51/VIII/2013, republicação em anexo), article 9(22) and (23): banking and financial operations, and insurance and reinsurance operations with the related services of brokers and intermediaries, are exempt without the right to deduct (field 09).', null, null, 50, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'civa-lei-51-2013', null, null, null, null),
  ('CV', 'CV-S-EXEMPT-HEALTH', 'IVA isento — serviços médicos e sanitários (venda)', '{}'::jsonb, null, 'percent', 0, 'sale', 'exempt', date '2014-01-01', null, 'Código do IVA (Lei n.º 51/VIII/2013, republicação em anexo), article 9(1): medical and sanitary services by doctors, dentists, nurses and other paramedics in the exercise of their profession, and by hospitals, clinics and dispensaries, are exempt without the right to deduct (field 09). Medicines and medical equipment (article 9(29)) are a separate exemption of goods by the Code''s annexed list, not modelled.', null, null, 40, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'civa-lei-51-2013', null, null, null, null),
  ('CV', 'CV-S-EXEMPT-RENT', 'IVA isento — locação de imóveis (venda)', '{}'::jsonb, null, 'percent', 0, 'sale', 'exempt', date '2014-01-01', null, 'Código do IVA (Lei n.º 51/VIII/2013, republicação em anexo), article 9(24): the letting of immovable property is exempt without the right to deduct (field 09), except hotel accommodation, parking areas, fixed installed machinery and the transfer of a business, and exhibition or advertising space, which stay taxable at 15 % (CV-S-15).', null, null, 60, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'civa-lei-51-2013', null, null, null, null),
  ('CV', 'CV-S-EXPORT', 'IVA isento com direito a dedução — exportações e operações assimiladas (venda)', '{}'::jsonb, null, 'percent', 0, 'sale', 'export', date '2014-01-01', null, 'Código do IVA (Lei n.º 51/VIII/2013, republicação em anexo), article 13(1)(a) and (b): goods dispatched or transported abroad by the seller, or by a buyer with no residence or establishment in Cabo Verde, are exempt; the exemption keeps the right to deduct the tax borne on purchases (Modelo 106 field 08). The customs or other documents that prove it (article 25(7)) are the user''s to keep; the Code makes the seller charge the tax without them (article 25(8)). The other cases of article 13 (ships, aircraft, diplomatic supplies) are not given a code of their own.', null, null, 20, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'civa-lei-51-2013', null, null, null, null)
on conflict (country, code) do update set
  name            = excluded.name,
  name_i18n       = excluded.name_i18n,
