insert into tax_report_templates
  (country, code, name, periods, period_default, valid_from, valid_to, legal_reference,
   is_periodic_return, deadline_rule, deadline_day, deadline_plus_days,
   deadline_reference, deadline_source_key, file_format)
values
  ('CV', 'CV-IVA-M106', 'Declaração periódica do IVA — Modelo 106 (mensal)', array['month']::declaration_period[], 'month'::declaration_period, date '2014-01-01', null, 'Código do IVA (Lei n.º 51/VIII/2013), article 25(1)(c): taxable persons file a return every month for the operations of the preceding month, with the tax due or the credit, even when no taxable operation took place (article 25(2)); article 37: by the last working day of the following month, or by the end of that month when the return is sent electronically. The form is the Modelo 106 (version 3.4) of the DNRE; the boxes here carry its field numbers. Fields 03 to 07, 10, 14 to 16, 25 to 31 and 37 to 50 (the Decreto-Lei 16/2004 cash regime, non-taxed operations, import VAT paid by the taxpayer, the pro rata, the regularisations, the carried credit, the refund and the breakdown tables) and the annexes of customers and suppliers are not modelled (README).', true,'last_day_of_month_after_period'::filing_deadline_rule, null, null, 'Código do IVA article 37(1): (a) by the last working day of the month following the one the operations belong to; (b) by the end of the following month when the return is sent electronically. Ekwo''s rule is the last calendar day, the electronic deadline; the paper deadline, one working day earlier at most, is not seen.', 'civa-lei-51-2013', null)
on conflict (country, code) do update set
  name                = excluded.name,
  periods             = excluded.periods,
  period_default      = excluded.period_default,
  valid_from          = excluded.valid_from,
  valid_to            = excluded.valid_to,
  legal_reference     = excluded.legal_reference,
  is_periodic_return  = excluded.is_periodic_return,
  deadline_rule       = excluded.deadline_rule,
  deadline_day        = excluded.deadline_day,
  deadline_plus_days  = excluded.deadline_plus_days,
  deadline_reference  = excluded.deadline_reference,
  deadline_source_key = excluded.deadline_source_key,
  file_format         = excluded.file_format;

