update country_defaults set
  numbering_gapless             = false,
  number_format                 = '{CODE}-{YYYY}-{NNNN}',
  legal_payment_days            = null,
  late_payment_reference        = null,
  numbering_legal_reference     = 'Código do IVA, article 25(1)(b): an invoice is issued for every supply of goods or services, even when the buyer does not ask for it. The numbering rules of the invoice (articles 32 and following, and the Portaria on invoicing) were not read; the sequential number per year is the pack''s example, not the official series, and the e-Fatura platform assigns its own authorised numbers (README).',
  numbering_source_key          = 'civa-lei-51-2013',
  payment_terms_legal_reference = null,
  payment_terms_source_key      = null,
  tax_point_rule                = 'delivery_date',
  tax_point_legal_reference     = 'Código do IVA, article 7(1): the tax is due and chargeable when the goods are placed at the buyer''s disposal and, for services, when they are performed; for continuous supplies with successive payments, at the end of the period each payment covers (article 7(3)). Article 8 adds the invoice rule (the tax is chargeable when the invoice is issued if it is issued before) that the pack does not model. `delivery_date` is the closest value of Ekwo''s vocabulary.',
  tax_point_source_key          = 'civa-lei-51-2013',
  posted_edit_policy            = null,
  posted_edit_policy_legal_reference = 'Código do IVA, article 25(6): an invoice is issued again when the taxable amount or the tax changes for any reason, including inaccuracy. A posted entry is therefore corrected with a credit note and a new invoice, not erased.',
  posted_edit_policy_source_key = 'civa-lei-51-2013',
  einvoice_profile              = null,
  einvoice_mandatory_from       = null,
  einvoice_obligation           = 'none',
  einvoice_legal_reference      = 'Cabo Verde has no Peppol authority, no EN 16931 profile and no ISO 6523 scheme a party is addressed by, so `profile`, `party_scheme` and `vat_scheme` are null and `obligation` is `none`. What the country has is a clearance-style platform run by the tax administration: the e-Fatura issues electronic invoices and other tax-relevant documents (DFE) as XML with a digital signature and an authorisation of use granted by the tax administration in real time, and says taxpayers previously accredited by it must issue them. The accreditation schedule by taxpayer was not found on the pages read. Ekwo does not connect to the platform; the gap is in the README and in docs/international.md.',
  einvoice_source_key           = 'efatura',
  party_scheme                  = null,
  vat_scheme                    = null,
  bank_account_scheme           = 'iban',
  bank_statement_formats        = null,
  payment_formats               = null,
  fiscal_year_default           = 'calendar'
 where country = 'CV';

